package com.chargeanim.pro\n\nimport android.content.ContentValues\nimport android.content.Context\nimport android.os.Build\nimport android.os.Environment\nimport android.provider.MediaStore\nimport java.io.PrintWriter\nimport java.io.StringWriter\nimport java.text.SimpleDateFormat\nimport java.util.Date\nimport java.util.Locale\n\n/** Last-resort crash recorder installed from Application.onCreate(). */\nobject CrashCapture {\n    private const val PREFS = "chargeflow_crash_capture"\n    private const val LAST_CRASH = "last_crash"\n\n    fun install(context: Context) {\n        val app = context.applicationContext\n        val previous = Thread.getDefaultUncaughtExceptionHandler()\n        Thread.setDefaultUncaughtExceptionHandler { thread, throwable ->\n            val report = buildReport(app, thread, throwable)\n            persist(app, report)\n            try { previous?.uncaughtException(thread, throwable) } catch (_: Throwable) { }\n        }\n    }\n\n    private fun buildReport(context: Context, thread: Thread, throwable: Throwable): String {\n        val stack = StringWriter()\n        PrintWriter(stack).use { throwable.printStackTrace(it) }\n        return buildString {\n            appendLine("ChargeFlow crash report")\n            appendLine("================================")\n            appendLine("Time: " + SimpleDateFormat("yyyy-MM-dd HH:mm:ss.SSS Z", Locale.US).format(Date()))\n            appendLine("Package: " + context.packageName)\n            appendLine("Android: " + Build.VERSION.RELEASE + " (API " + Build.VERSION.SDK_INT + ")")\n            appendLine("Device: " + Build.MANUFACTURER + " " + Build.MODEL)\n            appendLine("Thread: " + thread.name + " (" + thread.id + ")")\n            appendLine("Exception: " + throwable.javaClass.name)\n            appendLine("Message: " + throwable.message)\n            appendLine()\n            appendLine("Stack trace:")\n            appendLine(stack.toString())\n        }\n    }\n\n    private fun persist(context: Context, report: String) {\n        runCatching {\n            context.getSharedPreferences(PREFS, Context.MODE_PRIVATE).edit()\n                .putString(LAST_CRASH, report).commit()\n        }\n        runCatching {\n            context.openFileOutput("latest_crash.txt", Context.MODE_PRIVATE).use {\n                it.write(report.toByteArray(Charsets.UTF_8)); it.flush()\n            }\n        }\n        runCatching {\n            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.Q) {\n                val resolver = context.contentResolver\n                val values = ContentValues().apply {\n                    put(MediaStore.Downloads.DISPLAY_NAME, "ChargeFlow_crash_latest.txt")\n                    put(MediaStore.Downloads.MIME_TYPE, "text/plain")\n                    put(MediaStore.Downloads.RELATIVE_PATH, Environment.DIRECTORY_DOWNLOADS + "/ChargeFlow")\n                    put(MediaStore.Downloads.IS_PENDING, 1)\n                }\n                val uri = resolver.insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI, values)\n                    ?: return@runCatching\n                try {\n                    resolver.openOutputStream(uri)?.use { output ->\n                        output.write(report.toByteArray(Charsets.UTF_8)); output.flush()\n                    } ?: error("Unable to open crash report output stream")\n                    values.clear(); values.put(MediaStore.Downloads.IS_PENDING, 0)\n                    resolver.update(uri, values, null, null)\n                } catch (t: Throwable) {\n                    resolver.delete(uri, null, null, null); throw t\n                }\n            }\n        }\n    }\n}\n